private static boolean canTravel(int n, int x, int y, int endX, int endY, int[][] paths, boolean[][] visited) {
    if (x == endX && y == endY) {
        return true;
    }
    visited[x][y] = true;
    for (int[] path : paths) {
        int nextX = path[0];
        int nextY = path[1];
        if (isValidMove(x, y, nextX, nextY) && !visited[nextX][nextY]) {
            if (canTravel(n, nextX, nextY, endX, endY, paths, visited)) {
                return true;
            }
        }
    }
    return false;
}

private static boolean isValidMove(int x, int y, int nextX, int nextY) {
    return (Math.abs(x - nextX) == 1 && y == nextY) || (Math.abs(y - nextY) == 1 && x == nextX);
}

